// 1. Little's Law: Required Concurrency Slots (Threads / DB Connections)
function requiredConcurrency(rpsLambda: number, avgLatencySecondsW: number): number {
  return Math.ceil(rpsLambda * avgLatencySecondsW);
}

// 2. Fan-Out Tail Latency Amplification:
// Probability that a parent request calling K parallel leaves exceeds p99:
// P(parent > threshold) = 1 - (1 - p_leaf)^K
function fanoutSlowProbability(parallelCallsK: number, leafSlowProb = 0.01): number {
  return 1 - Math.pow(1 - leafSlowProb, parallelCallsK);
}
// Example: K = 50 shards at p99 (0.01) => 1 - (0.99)^50 = 0.395 (39.5% of requests hit p99!)

// 1. AWS Architecture Blog 'Full Jitter' Backoff Formula
function calcFullJitterBackoffMs(attempt: number, baseMs = 50, capMs = 5000): number {
  const expCeiling = Math.min(capMs, baseMs * Math.pow(2, attempt));
  return Math.floor(Math.random() * expCeiling);
}

// 2. Client-Side Retry Budget (Max 10% extra retry traffic across fleet)
// Every normal request deposits 0.1 tokens; every retry consumes 1.0 token.
// If token bucket is empty, fail fast immediately without retrying!
class RetryBudget {
  private tokens = 10;
  private readonly maxTokens = 100;
  public recordRequest(): void {
    this.tokens = Math.min(this.maxTokens, this.tokens + 0.1);
  }
  public tryConsumeRetry(): boolean {
    if (this.tokens >= 1.0) { this.tokens -= 1.0; return true; }
    return false; // Outage detected: suppress retry storm!
  }
}

interface WorkloadSpec {
  dau: number;                  // e.g., 50_000_000
  readsPerUserPerDay: number;   // e.g., 40
  writesPerUserPerDay: number;  // e.g., 4
  recordSizeBytes: number;      // e.g., 1024 (1 KB)
  peakMultiplier: number;       // e.g., 3.5
  azFailureHeadroom: number;    // e.g., 1.5 (survive 1 of 3 AZ loss)
}

export function calculateCapacityPlan(spec: WorkloadSpec) {
  const avgReadRps = (spec.dau * spec.readsPerUserPerDay) / 86400;
  const avgWriteRps = (spec.dau * spec.writesPerUserPerDay) / 86400;
  const designPeakReadRps = avgReadRps * spec.peakMultiplier * spec.azFailureHeadroom;
  const designPeakWriteRps = avgWriteRps * spec.peakMultiplier * spec.azFailureHeadroom;
  const dailyStorageBytes = spec.dau * spec.writesPerUserPerDay * spec.recordSizeBytes;
  const hotWorkingSetRamBytes = dailyStorageBytes * 7 * 0.20; // 20% of 7-day window
  return { avgReadRps, avgWriteRps, designPeakReadRps, designPeakWriteRps, dailyStorageBytes, hotWorkingSetRamBytes };
}

// Serverless (Lambda / DynamoDB On-Demand) excels at spiky, low-utilization workloads,
// but costs 3x-6x more than provisioned compute once utilization exceeds ~35%.
function compareMonthlyComputeCost(avgRps: number, avgDurationMs: number, memoryGb: number) {
  const monthlyRequests = avgRps * 86400 * 30;
  const totalGbSeconds = monthlyRequests * (avgDurationMs / 1000) * memoryGb;

  // 1. Serverless Pricing (~$0.0000166667 per GB-s + $0.20 per 1M requests)
  const serverlessCost = (totalGbSeconds * 0.0000166667) + ((monthlyRequests / 1e6) * 0.20);

  // 2. Provisioned ARM64 Containers (Assuming 50% target utilization + 1yr Savings Plan)
  const concurrentSlotsNeeded = (avgRps * (avgDurationMs / 1000)) / 0.50;
  const provisionedGbMonth = concurrentSlotsNeeded * memoryGb;
  const provisionedCost = provisionedGbMonth * 12.50; // ~$12.50 per GB-month on Graviton
  return { serverlessCost: Math.round(serverlessCost), provisionedCost: Math.round(provisionedCost) };
}

// Achieve 'Read-Your-Writes' consistency on async read replicas without querying Primary
// for every read! Stick a monotonic Log Sequence Number (LSN) in client session state.
async function readUserProfile(userId: string, clientMinLsn: bigint) {
  const localReplica = getNearestReadReplica();

  // Fast path: 99.5% of the time, the async replica has already caught up past clientMinLsn
  if (localReplica.lastAppliedWalLsn() >= clientMinLsn) {
    return localReplica.query('SELECT * FROM users WHERE id = $1', [userId]);
  }

  // Fallback path: User just mutated their profile <50ms ago; route to Primary
  // (or wait briefly for replica LSN to catch up)
  return primaryDb.query('SELECT * FROM users WHERE id = $1', [userId]);
}

// Anti-Pattern: Dynamic Control-Plane Reconfiguration during an outage
// Good Pattern: 'Constant Work' - Always send a fixed-size heartbeat array
// for all 64 shards every second. Flipping a shard healthy/unhealthy
// changes a single bit (0 -> 1) without allocating memory, opening sockets,
// or mutating routing tables!
export class ConstantWorkHealthBroadcaster {
  private readonly statusBitmap = new Uint8Array(64); // Fixed 64 bytes always!

  public setShardStatus(shardId: number, healthy: boolean): void {
    this.statusBitmap[shardId] = healthy ? 1 : 0;
  }

  public broadcastTick(udpSocket: DatagramSocket): void {
    // Exact same packet size, CPU cost, and network footprint during calm OR crisis
    udpSocket.send(this.statusBitmap);
  }
}

async function getOrderDetails(orderId: string): Promise<OrderResponse> {
  if (featureFlags.isEnabled('route-orders-to-microservice', orderId)) {
    return orderMicroserviceClient.getOrder(orderId);
  }

  // Legacy path remains authoritative while shadowing 10% to new microservice
  const legacyResult = await monolithOrderRepo.findById(orderId);
  if (Math.random() < 0.10) {
    void orderMicroserviceClient.getOrder(orderId).then((newResult) => {
      if (!deepEqual(legacyResult, newResult)) {
        metrics.increment('strangler.order_read_parity_mismatch');
      }
    }).catch(() => metrics.increment('strangler.order_shadow_error'));
  }
  return legacyResult;
}

// At 100,000 RPS, even a single Redis key ('viral_video_views') melts at ~100k ops/sec
// Solution: Coalesce writes in local pod memory for 1000ms before flushing 1 HINCRBY to Redis!
export class WriteBehindCounterAggregator {
  private localDeltas = new Map<string, number>();

  public increment(entityId: string, delta = 1): void {
    this.localDeltas.set(entityId, (this.localDeltas.get(entityId) ?? 0) + delta);
  }

  // Invoked every 1,000ms by background timer
  public async flushToDistributedStore(redis: RedisClient): Promise<void> {
    const batch = new Map(this.localDeltas);
    this.localDeltas.clear();
    const pipeline = redis.pipeline();
    for (const [id, count] of batch.entries()) {
      pipeline.hincrby('entity_counters', id, count);
    }
    await pipeline.exec(); // Reduces 50,000 network ops/sec -> 1 batched pipeline/sec!
  }
}

// Shuffle Sharding: Assign each tenant K=4 workers out of N=8 total workers.
// Number of unique virtual shards = C(8, 4) = 8! / (4! * 4!) = 70 virtual shards!
// If 1 noisy tenant saturates all 4 of its assigned workers, only 1/70 (1.4%) of other
// tenants share all 4 workers—compared to 1/2 (50%) in standard 2-shard partitioning!
export function assignShuffleShardWorkers(
  tenantId: string,
  totalWorkersN = 8,
  shardSizeK = 4
): number[] {
  const selected = new Set<number>();
  let salt = 0;
  while (selected.size < shardSizeK) {
    const hash = fnv1aHash(tenantId + ':' + salt++);
    selected.add(hash % totalWorkersN);
  }
  return Array.from(selected);
}
